script:
paths = ["data/a.txt", "data/b.txt"]
result = {}
total = 0
for p in paths:
    c = repo.read(p)
    nlines = len(c.split("\n"))
    if c.endswith("\n"):
        nlines -= 1
    n_newlines = c.count("\n")
    result[p] = {"wc_l_newlines": n_newlines, "logical_lines": nlines, "ends_with_newline": c.endswith("\n")}
    total += n_newlines
return {"per_file": result, "total_newlines": total, "raw": {p: repo.read(p) for p in paths}}
